/*!
 * \file stub_reg.cpp
 * \brief
 */
#include "stub_reg.h"
#include <string>
#include <dlfcn.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <csignal>
#include "securec.h"

const char* g_regStubs[INTRI_TYPE_MAX]{
    "AscendC",
    "cceprint",
    "npuchk",
};

namespace AscendC {
const int SYM_LEN_MAX = 511;

void StubReg(IntriTypeT type, const char* stub) { g_regStubs[type] = stub; }

void StubInit(void)
{
    char buf[SYM_LEN_MAX + 1];
    static bool gStubInited = false;
    if (gStubInited) {
        return;
    }
    gStubInited = true;

    int32_t logfd = open("stub_reg.log", O_CREAT | O_WRONLY | O_TRUNC, S_IRUSR | S_IWUSR);
    for (int32_t s = 0; s < INTRI_TYPE_MAX; s++) {
        const char* stub = g_regStubs[s];
        if (stub == nullptr) {
            continue;
        }
        int32_t slen = strnlen(stub, SYM_LEN_MAX);
